    move_one_ball([3, 4, 5, 1, 2])==>True
    move_one_ball([3, 5, 4, 1, 2])==>False

    Consider the array as a circular buffer to determine if it can be rotated into a sorted order.
    """

    def is_non_decreasing(arr):
        for i in range(len(arr) - 1):
            if arr[i] > arr[i + 1]:
                return False
        return True

    def rotate_array(arr):
        return arr[-1:] + arr[:-1]

    if not arr:
        return True

    if is_non_decreasing(arr):
        return True

    sorted_arr = sorted(arr)
    for _ in range(len(arr)):
        arr = rotate_array(arr)
        if arr == sorted_arr:
            return True

    return False

